const TransactionList = ({ transactions }) => {
    return (
      <ul>
        {transactions.map((transaction, index) => (
          <li key={index}>
            {transaction.description} - ${transaction.amount}
          </li>
        ))}
      </ul>
    );
  };
  
  export default TransactionList;
